  useEffect(()=>{
    const sequence=["ArrowUp","ArrowUp","ArrowDown","ArrowDown","ArrowLeft","ArrowRight","ArrowLeft","ArrowRight","b","a"];
    const onSecretKey=(event:KeyboardEvent)=>{
      if(event.ctrlKey||event.metaKey||event.altKey)return;
      const next=[...konamiRef.current,event.key].slice(-sequence.length);
      konamiRef.current=next;
      if(next.length===sequence.length&&sequence.every((key,index)=>key.toLowerCase()===next[index].toLowerCase())){
        konamiRef.current=[];
        void unlockAchievement("code_master");showEasterEgg("🎮 Код принят. Добро пожаловать в секретный режим DTR!");
      }
    };
    window.addEventListener("keydown",onSecretKey);
    return()=>window.removeEventListener("keydown",onSecretKey);
  },[token,me?.id]);

  const [page,setPage] = useState<Page>("chat");
