  const [typingName,setTypingName]=useState("");
  const typingTimerRef=useRef<ReturnType<typeof setTimeout>|null>(null);
  const seenIncomingIdsRef=useRef<Set<string>>(new Set());
  const [editingMessage,setEditingMessage]=useState<Message|null>(null);
  const [forwardTarget,setForwardTarget]=useState<Message|null>(null);
  const [messageSearchOpen,setMessageSearchOpen]=useState(false);
  const [messageSearch,setMessageSearch]=useState("");
  // Keyboard shortcuts for desktop users; touch controls remain unchanged.
  useEffect(()=>{
    const onKeyDown=(event:KeyboardEvent)=>{
      if(event.key==="Escape"){
        if(messageSearchOpen){setMessageSearchOpen(false);setMessageSearch("");event.preventDefault();return;}
        if(searchOpen){setSearch("");setResults([]);setSearchOpen(false);event.preventDefault();return;}
        if(replyTarget){setReplyTarget(null);event.preventDefault();}
        return;
      }
      if(!(event.ctrlKey||event.metaKey)||event.altKey)return;
      const key=event.key.toLowerCase();
      if(key==="k"){
        event.preventDefault();
        setSearchOpen(true);setSearch("");setResults([]);
      }else if(key==="f"&&page==="chat"&&active){
        event.preventDefault();
        setMessageSearchOpen(true);setMessageSearch("");
      }
    };
    window.addEventListener("keydown",onKeyDown);
    return()=>window.removeEventListener("keydown",onKeyDown);
  },[active,page,searchOpen,messageSearchOpen,replyTarget]);
  const [emojiOpen,setEmojiOpen] = useState(false);
  const [composerMoreOpen,setComposerMoreOpen]=useState(false);
