  const [editName,setEditName] = useState("");
  const [editBio,setEditBio] = useState("");
  const [editAge,setEditAge] = useState("");
  const [editAgePublic,setEditAgePublic] = useState(false);
  const [groupOpen,setGroupOpen] = useState(false);
  const [groupTitle,setGroupTitle] = useState("");
  const [groupSearch,setGroupSearch] = useState("");
  const [groupResults,setGroupResults] = useState<User[]>([]);
  const [selectedUsers,setSelectedUsers] = useState<User[]>([]);
  const [groupInfoOpen,setGroupInfoOpen] = useState(false);
  const [groupAddSearch,setGroupAddSearch] = useState("");
  const [groupAddResults,setGroupAddResults] = useState<User[]>([]);
  const [recording,setRecording] = useState(false);
  const [uploadingMedia,setUploadingMedia] = useState(false);
  const [compact,setCompact] = useState(localStorage.getItem("dtr_compact")==="true");
  const [theme,setTheme] = useState<"dark"|"light">(localStorage.getItem("dtr_theme")==="light"?"light":"dark");
  const [notes,setNotes] = useState<any[]>([]);
  const [noteTitle,setNoteTitle] = useState("");
  const [noteBody,setNoteBody] = useState("");
