  const recorderChunks = useRef<Blob[]>([]);
  const recorderTimer = useRef<number|null>(null);
  const socket = useMemo<Socket|null>(()=> token ? io({auth:{token}}) : null,[token]);

  // Escape closes the topmost overlay first, matching desktop and mobile expectations.
  useEffect(()=>{
    const closeOverlay=(event:KeyboardEvent)=>{
      if(event.key!=="Escape")return;
      if(groupInfoOpen)setGroupInfoOpen(false);
      else if(groupOpen)setGroupOpen(false);
      else if(editOpen)setEditOpen(false);
      else if(profileTarget)setProfileTarget(null);
      else if(forwardTarget)setForwardTarget(null);
      else if(emojiOpen)setEmojiOpen(false);
      else if(composerMoreOpen)setComposerMoreOpen(false);
      else return;
      event.preventDefault();
      event.stopPropagation();
    };
    window.addEventListener("keydown",closeOverlay);
    return()=>window.removeEventListener("keydown",closeOverlay);
  },[groupInfoOpen,groupOpen,editOpen,profileTarget,forwardTarget,emojiOpen,composerMoreOpen]);

  // Keep the underlying messenger viewport fixed while a modal is open.
  // Telegram's Android WebView can otherwise scroll the page when a modal closes.
  useEffect(()=>{
    const modalOpen=Boolean(profileTarget||editOpen||groupOpen||groupInfoOpen);
    if(!modalOpen)return;
    const y=window.scrollY||document.documentElement.scrollTop||0;
    const body=document.body;
    const previous={position:body.style.position,top:body.style.top,left:body.style.left,right:body.style.right,width:body.style.width,overflow:body.style.overflow};
    body.style.position="fixed";
    body.style.top=`-${y}px`;
    body.style.left="0";
    body.style.right="0";
    body.style.width="100%";
    body.style.overflow="hidden";
    return ()=>{
      body.style.position=previous.position;
      body.style.top=previous.top;
      body.style.left=previous.left;
      body.style.right=previous.right;
      body.style.width=previous.width;
      body.style.overflow=previous.overflow;
      window.scrollTo(0,y);
    };
  },[profileTarget,editOpen,groupOpen,groupInfoOpen]);

  async function refreshChats(){ if(!token)return; try{const d=await api("/chats",token);setChats(d.chats||[]);}catch(e:any){setError(e.message)} }
  async function loadContacts(){if(!token)return;setContactsLoading(true);try{const d=await api("/contacts",token);setFriends(d.friends||[]);setIncomingFriendRequests(d.incoming||[]);setOutgoingFriendRequests(d.outgoing||[]);setFavoriteIds((d.favorites||[]).map((u:User)=>String(u.id)));}catch(e:any){setError(e.message)}finally{setContactsLoading(false)}}
  async function sendFriendRequest(user:User){try{const d=await api("/friends/request",token,{method:"POST",body:JSON.stringify({userId:user.id})});setError(d.message||"Заявка отправлена");await loadContacts();}catch(e:any){setError(e.message)}}
  async function answerFriendRequest(requestId:string,action:"accept"|"reject"){try{await api("/friends/requests/"+requestId,token,{method:"PATCH",body:JSON.stringify({action})});await loadContacts();}catch(e:any){setError(e.message)}}
  async function removeFriend(user:User){try{await api("/friends/"+user.id,token,{method:"DELETE"});await loadContacts();}catch(e:any){setError(e.message)}}
  async function toggleFavorite(user:User){const isFavorite=favoriteIds.includes(String(user.id));try{await api("/favorites/"+user.id,token,{method:isFavorite?"DELETE":"POST",body:isFavorite?undefined:JSON.stringify({})});setFavoriteIds(old=>isFavorite?old.filter(id=>id!==String(user.id)):[...old,String(user.id)]);}catch(e:any){setError(e.message)}}
  useEffect(()=>{ if(!token)return; api("/me",token).then(d=>{setMe(d.user);setTheme(d.user.theme==="light"?"light":"dark");localStorage.setItem("dtr_theme",d.user.theme==="light"?"light":"dark");setEditName(d.user.displayName);setEditBio(d.user.bio||"");setEditAge(d.user.age===null?"":String(d.user.age));setEditAgePublic(Boolean(d.user.agePublic));}).catch(()=>logout()); refreshChats(); return ()=>{socket?.disconnect()}; },[token,socket]);
